const compassN3Topics = {"compass-n3-1":"Qualifying a statement","compass-n3-2":"Saying an action is unnecessary","compass-n3-3":"Explaining an unwanted result","compass-n3-4":"Describing repeated occasions","compass-n3-5":"Acting while a condition lasts","compass-n3-6":"Adding a convenient extra errand","compass-n3-7":"Following an example or instructions","compass-n3-8":"Leaving a state unchanged","compass-n3-9":"Passing on an instruction","compass-n3-10":"Ruling out an explanation","compass-n3-11":"Considering a hypothetical situation","compass-n3-12":"Substitution and trade-offs","compass-n3-13":"Choosing the only available action","compass-n3-14":"Attempting or being about to act","compass-n3-15":"Inferring a cause or naming reason","compass-n3-16":"Reading a turn against expectations"};
const compassN3Bank = [{"sourceId":"compass-n3-1-q1","level":3,"skill":4,"prompt":"毎日使うが、操作が簡単な___。 (I use it daily, but that doesn’t mean it is easy to operate.)","options":["わけではない","に違いない","に決まっている","にすぎない"],"why":"Use 〜わけではない to deny a broad conclusion. It leaves room for exceptions. あまり食べない can describe behavior without implying dislike.","offset":0.12,"family":"compass-n3-1-grammar","lessonId":"compass-n3-1","topicId":"compass-n3-1-grammar"},{"sourceId":"compass-n3-1-q2","level":3,"skill":4,"prompt":"彼に賛成しないが、意見を聞きたくない___。 (I disagree, but that doesn’t mean I don’t want to hear his opinion.)","options":["わけではない","ばかりだ","おそれがある","ことにした"],"why":"Use 〜わけではない to deny a broad conclusion. It leaves room for exceptions. あまり食べない can describe behavior without implying dislike.","offset":0.12,"family":"compass-n3-1-grammar","lessonId":"compass-n3-1","topicId":"compass-n3-1-grammar"},{"sourceId":"compass-n3-2-q1","level":3,"skill":4,"prompt":"資料は電子版もあるから、わざわざ印刷する___。 (There is an electronic copy, so there is no need to print it.)","options":["ことはない","わけがない","ところだった","ことにした"],"why":"Dictionary form + ことはない tells someone there is no need to act. It often reassures someone who feels pressure.","offset":0.12,"family":"compass-n3-2-grammar","lessonId":"compass-n3-2","topicId":"compass-n3-2-grammar"},{"sourceId":"compass-n3-2-q2","level":3,"skill":4,"prompt":"全員分の席を取ってあるので、早く来る___。 (Seats are reserved for everyone, so there is no need to come early.)","options":["ことはありません","つもりはありません","はずがありません","しかありません"],"why":"Dictionary form + ことはない tells someone there is no need to act. It often reassures someone who feels pressure.","offset":0.12,"family":"compass-n3-2-grammar","lessonId":"compass-n3-2","topicId":"compass-n3-2-grammar"},{"sourceId":"compass-n3-3-q1","level":3,"skill":4,"prompt":"目覚ましが鳴らなかった___、面接に遅れた。 (I blame the alarm failing for being late to the interview.)","options":["せいで","たびに","おかげで","ついでに"],"why":"Use 〜せいで for a cause blamed for an undesirable result. Use おかげで to give credit for a favorable result.","offset":0.12,"family":"compass-n3-3-grammar","lessonId":"compass-n3-3","topicId":"compass-n3-3-grammar"},{"sourceId":"compass-n3-3-q2","level":3,"skill":4,"prompt":"同僚が手伝ってくれた___、締め切りに間に合った。 (Thanks to my colleague, I met the deadline.)","options":["おかげで","せいで","うちに","かわりに"],"why":"Use 〜せいで for a cause blamed for an undesirable result. Use おかげで to give credit for a favorable result.","offset":0.12,"family":"compass-n3-3-grammar","lessonId":"compass-n3-3","topicId":"compass-n3-3-grammar"},{"sourceId":"compass-n3-4-q1","level":3,"skill":4,"prompt":"写真を見返す___、旅行のことを思い出す。 (Every time I look at the photos again, I remember the trip.)","options":["たびに","うちに","ついでに","ために"],"why":"Dictionary form or noun + の + たびに means every time. It connects a recurring trigger with a recurring result.","offset":0.12,"family":"compass-n3-4-grammar","lessonId":"compass-n3-4","topicId":"compass-n3-4-grammar"},{"sourceId":"compass-n3-4-q2","level":3,"skill":4,"prompt":"引っ越しの___、使わない物を処分する。 (Every time I move, I get rid of things I do not use.)","options":["たびに","途中で","かわりに","まま"],"why":"Dictionary form or noun + の + たびに means every time. It connects a recurring trigger with a recurring result.","offset":0.12,"family":"compass-n3-4-grammar","lessonId":"compass-n3-4","topicId":"compass-n3-4-grammar"},{"sourceId":"compass-n3-5-q1","level":3,"skill":4,"prompt":"雨が降らない___、荷物を車に運ぼう。 (Let’s carry the luggage to the car before it starts raining.)","options":["うちに","せいで","たびに","に比べて"],"why":"Use 〜うちに to act before a situation changes. With a negative form it can mean before something happens.","offset":0.12,"family":"compass-n3-5-grammar","lessonId":"compass-n3-5","topicId":"compass-n3-5-grammar"},{"sourceId":"compass-n3-5-q2","level":3,"skill":4,"prompt":"明るい___、駅まで歩いておこう。 (Let’s walk to the station while it is still light.)","options":["うちに","わけで","ことから","ために"],"why":"Use 〜うちに to act before a situation changes. With a negative form it can mean before something happens.","offset":0.12,"family":"compass-n3-5-grammar","lessonId":"compass-n3-5","topicId":"compass-n3-5-grammar"},{"sourceId":"compass-n3-6-q1","level":3,"skill":4,"prompt":"銀行に行く___、近くの薬局にも寄ってきます。 (While I’m going to the bank anyway, I’ll stop at the nearby pharmacy.)","options":["ついでに","せいで","ばかりに","たびに"],"why":"Use 〜ついでに when the main action creates a convenient chance to do something else. A noun takes の before ついでに.","offset":0.12,"family":"compass-n3-6-grammar","lessonId":"compass-n3-6","topicId":"compass-n3-6-grammar"},{"sourceId":"compass-n3-6-q2","level":3,"skill":4,"prompt":"散歩の___、ポストに手紙を入れた。 (While out on my walk, I mailed a letter.)","options":["ついでに","おそれで","せいで","はずで"],"why":"Use 〜ついでに when the main action creates a convenient chance to do something else. A noun takes の before ついでに.","offset":0.12,"family":"compass-n3-6-grammar","lessonId":"compass-n3-6","topicId":"compass-n3-6-grammar"},{"sourceId":"compass-n3-7-q1","level":3,"skill":4,"prompt":"受付で聞いた___、申込書を書いてください。 (Fill out the form exactly as explained at reception.)","options":["とおりに","うちに","せいで","たびに"],"why":"Use 〜とおりに for an action that follows a model, order, or instruction. Use noun + のとおりに.","offset":0.12,"family":"compass-n3-7-grammar","lessonId":"compass-n3-7","topicId":"compass-n3-7-grammar"},{"sourceId":"compass-n3-7-q2","level":3,"skill":4,"prompt":"組み立ては説明書の___進めてください。 (Proceed with assembly according to the manual.)","options":["とおりに","ままに","ために","せいで"],"why":"Use 〜とおりに for an action that follows a model, order, or instruction. Use noun + のとおりに.","offset":0.12,"family":"compass-n3-7-grammar","lessonId":"compass-n3-7","topicId":"compass-n3-7-grammar"},{"sourceId":"compass-n3-8-q1","level":3,"skill":4,"prompt":"電気をつけた___、部屋を出てしまった。 (I left the room with the lights still on.)","options":["まま","たびに","おかげで","とおりに"],"why":"Use 〜たまま or noun + のまま when a condition stays in place while something else happens.","offset":0.12,"family":"compass-n3-8-grammar","lessonId":"compass-n3-8","topicId":"compass-n3-8-grammar"},{"sourceId":"compass-n3-8-q2","level":3,"skill":4,"prompt":"名前を書かない___、用紙を出してしまった。 (I submitted the form with my name still unwritten.)","options":["まま","ついでに","ことから","たびに"],"why":"Use 〜たまま or noun + のまま when a condition stays in place while something else happens.","offset":0.12,"family":"compass-n3-8-grammar","lessonId":"compass-n3-8","topicId":"compass-n3-8-grammar"},{"sourceId":"compass-n3-9-q1","level":3,"skill":4,"prompt":"係員は客に、列から離れない___言った。 (The attendant told customers not to leave the line.)","options":["ように","たびに","ところで","うちに"],"why":"Dictionary or negative form + ように言う reports an instruction about what someone should or should not do.","offset":0.12,"family":"compass-n3-9-grammar","lessonId":"compass-n3-9","topicId":"compass-n3-9-grammar"},{"sourceId":"compass-n3-9-q2","level":3,"skill":4,"prompt":"部長に、会議の前に資料を確認する___言われた。 (The manager told me to check the materials before the meeting.)","options":["ように","おかげで","ついでに","せいで"],"why":"Dictionary or negative form + ように言う reports an instruction about what someone should or should not do.","offset":0.12,"family":"compass-n3-9-grammar","lessonId":"compass-n3-9","topicId":"compass-n3-9-grammar"},{"sourceId":"compass-n3-10-q1","level":3,"skill":4,"prompt":"この店は今日休みだから、中で買い物ができる___。 (The shop is closed today, so there is no way we can shop inside.)","options":["わけがない","ようになった","つもりだ","かもしれない"],"why":"Use 〜わけがない when the available facts make something seem impossible. It is much stronger than かもしれない.","offset":0.12,"family":"compass-n3-10-grammar","lessonId":"compass-n3-10","topicId":"compass-n3-10-grammar"},{"sourceId":"compass-n3-10-q2","level":3,"skill":4,"prompt":"まだ発送されていない品物が、もう届いた___。 (There is no way an item that has not been shipped has already arrived.)","options":["わけがない","ばかりだ","ことがある","ところだ"],"why":"Use 〜わけがない when the available facts make something seem impossible. It is much stronger than かもしれない.","offset":0.12,"family":"compass-n3-10-grammar","lessonId":"compass-n3-10","topicId":"compass-n3-10-grammar"},{"sourceId":"compass-n3-11-q1","level":3,"skill":4,"prompt":"来年海外で働く___、今から何を準備しますか。 (Supposing you work abroad next year, what will you prepare now?)","options":["としたら","ついでに","とおりに","たびに"],"why":"Use 〜としたら to make an assumption and ask or say what would follow if it were true.","offset":0.12,"family":"compass-n3-11-grammar","lessonId":"compass-n3-11","topicId":"compass-n3-11-grammar"},{"sourceId":"compass-n3-11-q2","level":3,"skill":4,"prompt":"列車が止まる___、バスで会場まで行けるだろうか。 (Suppose the trains stop. Can we reach the venue by bus?)","options":["としたら","せいで","おかげで","ところで"],"why":"Use 〜としたら to make an assumption and ask or say what would follow if it were true.","offset":0.12,"family":"compass-n3-11-grammar","lessonId":"compass-n3-11","topicId":"compass-n3-11-grammar"},{"sourceId":"compass-n3-12-q1","level":3,"skill":4,"prompt":"担当者が休みなので、私が担当者の___、会議に出ます。 (The person in charge is off, so I’ll attend in their place.)","options":["かわりに","たびに","ついでに","せいで"],"why":"Use 〜かわりに for a substitute or a trade-off. With a person, noun + のかわりに often means in their place.","offset":0.12,"family":"compass-n3-12-grammar","lessonId":"compass-n3-12","topicId":"compass-n3-12-grammar"},{"sourceId":"compass-n3-12-q2","level":3,"skill":4,"prompt":"この部屋は狭い___、駅にとても近い。 (The room is small, but it is very close to the station in exchange.)","options":["かわりに","ために","うちに","とおりに"],"why":"Use 〜かわりに for a substitute or a trade-off. With a person, noun + のかわりに often means in their place.","offset":0.12,"family":"compass-n3-12-grammar","lessonId":"compass-n3-12","topicId":"compass-n3-12-grammar"},{"sourceId":"compass-n3-13-q1","level":3,"skill":4,"prompt":"道が通行止めなので、別の道を探す___。 (The road is closed, so our only option is to find another route.)","options":["しかない","わけがない","ことはない","おそれがある"],"why":"Dictionary form + しかない says the named action is the only practical option. It differs from noun + しか + negative, which limits quantity or choice.","offset":0.12,"family":"compass-n3-13-grammar","lessonId":"compass-n3-13","topicId":"compass-n3-13-grammar"},{"sourceId":"compass-n3-13-q2","level":3,"skill":4,"prompt":"資料を保存しなかったから、もう一度書く___。 (I did not save it, so rewriting it is my only option.)","options":["しかない","ことにならない","つもりがない","はずがない"],"why":"Dictionary form + しかない says the named action is the only practical option. It differs from noun + しか + negative, which limits quantity or choice.","offset":0.12,"family":"compass-n3-13-grammar","lessonId":"compass-n3-13","topicId":"compass-n3-13-grammar"},{"sourceId":"compass-n3-14-q1","level":3,"skill":3,"prompt":"家を出___としたとき、宅配便が来た。 (Just as I was about to leave, a delivery arrived.)","options":["よう","て","た","る"],"why":"Volitional form + とする describes an attempt. 〜ようとしたとき often marks the moment just before an action.","offset":0.12,"family":"compass-n3-14-grammar","lessonId":"compass-n3-14","topicId":"compass-n3-14-grammar"},{"sourceId":"compass-n3-14-q2","level":3,"skill":3,"prompt":"パソコンを閉じ___とした瞬間、メッセージが届いた。 (At the moment I was about to close my laptop, a message arrived.)","options":["よう","ない","た","る"],"why":"Volitional form + とする describes an attempt. 〜ようとしたとき often marks the moment just before an action.","offset":0.12,"family":"compass-n3-14-grammar","lessonId":"compass-n3-14","topicId":"compass-n3-14-grammar"},{"sourceId":"compass-n3-15-q1","level":3,"skill":4,"prompt":"白い花が多く咲く___、この丘は「白花の丘」と呼ばれている。 (The hill got its name because many white flowers bloom there.)","options":["ことから","ことができて","ことにして","ことはなく"],"why":"Use 〜ことから to state an observed fact that explains a name, decision, or inference. It is common in explanatory writing.","offset":0.12,"family":"compass-n3-15-grammar","lessonId":"compass-n3-15","topicId":"compass-n3-15-grammar"},{"sourceId":"compass-n3-15-q2","level":3,"skill":4,"prompt":"窓が内側から開けられていた___、誰かが中にいたと考えられた。 (The window having been opened from the inside led to the inference that someone was inside.)","options":["ことから","ことにして","たびに","ついでに"],"why":"Use 〜ことから to state an observed fact that explains a name, decision, or inference. It is common in explanatory writing.","offset":0.12,"family":"compass-n3-15-grammar","lessonId":"compass-n3-15","topicId":"compass-n3-15-grammar"},{"sourceId":"compass-n3-16-q1","level":3,"skill":4,"prompt":"天気予報は晴れだった。___、朝から雪が降った。 (The forecast said clear skies. Instead, it snowed from morning.)","options":["ところが","したがって","たとえば","つまり"],"why":"ところが opens a sentence that gives an unexpected result. The first sentence creates an expectation and the next reverses it.","offset":0.12,"family":"compass-n3-16-grammar","lessonId":"compass-n3-16","topicId":"compass-n3-16-grammar"},{"sourceId":"compass-n3-16-q2","level":3,"skill":4,"prompt":"簡単な問題だと思った。___、誰も答えられなかった。 (I thought it was an easy question. Contrary to my expectation, nobody could answer.)","options":["ところが","そのため","すなわち","たとえば"],"why":"ところが opens a sentence that gives an unexpected result. The first sentence creates an expectation and the next reverses it.","offset":0.12,"family":"compass-n3-16-grammar","lessonId":"compass-n3-16","topicId":"compass-n3-16-grammar"}];
for (const row of compassN3Bank) bank.push({...row,id:bank.length});
